{"packet_id":"D083-01","doc_id":"D083","jurisdiction":"San Francisco, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Rent Ordinance relocation payments for no-fault evictions","requirement":"For eviction notices served 3/01/26–2/28/27 based on owner/relative move-in, demolition, temporary capital improvement or substantial rehabilitation, the landlord must pay $8,245.00 per tenant (max $24,733.00 per unit) plus $5,497.00 for each elderly or disabled tenant or household with minor children.","key_value":"$8,245.00/tenant; $24,733.00/unit max; +$5,497.00 (3/01/26–2/28/27)","coverage_conditions":"Evictions based on owner/relative move-in, demolition or permanent removal of the unit from housing use, temporary capital improvement work, or substantial rehabilitation; notices served 3/01/26 – 2/28/27.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"No-fault evictions: owner/relative move-in, demolition, temporary capital improvement, substantial rehabilitation"},"exemptions":"Temporary capital improvement evictions of less than 20 days, which the page says are governed by Cal. Civ. Code § 1947.9 and not by Rent Ordinance § 37.9C.","penalty":null,"effective_date":"2026-03-01","citation":"S.F. Admin. Code § 37.9C","quoted_span":"3/01/26 – 2/28/27 $8,245.00 $24,733.00 $5,497.00","interaction":null,"confidence":0.85,"conflict_flag":false,"conflict_note":null}
