{"packet_id":"D083-01","doc_id":"D083","jurisdiction":"CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Relocation payments for temporary displacement under 20 days","requirement":"For temporary displacement of less than 20 days for temporary capital improvement work, the landlord must pay the tenant household $446.00 per day plus actual moving expenses when the eviction notice is served 3/01/26–2/28/27.","key_value":"$446.00/day plus moving expenses (3/01/26–2/28/27)","coverage_conditions":"Tenant households temporarily displaced for temporary capital improvement work of less than 20 days; the page says this amount is governed by Cal. Civ. Code § 1947.9.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Temporary displacement of less than 20 days for temporary capital improvement work"},"exemptions":null,"penalty":null,"effective_date":"2026-03-01","citation":"Cal. Civ. Code § 1947.9","quoted_span":"3/01/26 – 2/28/27 $446.00/day (plus actual moving expenses)","interaction":"Page states these payments are governed by Cal. Civ. Code § 1947.9 and not by Rent Ordinance Section 37.9C.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
